mapper.select:
SELECT f.*, t.name as teacher_name, b.title as book_title FROM fine f LEFT JOIN teacher t ON f.teacher_id = t.id LEFT JOIN borrow_record br ON f.borrow_id = br.id LEFT JOIN book b ON br.book_id = b.id WHERE f.teacher_id = #{teacherId}
AND f.status = #{status}
ORDER BY f.fine_date DESC

SELECT COUNT(*) FROM fine f LEFT JOIN teacher t ON f.teacher_id = t.id
AND t.name LIKE CONCAT('%', #{teacherName}, '%')
AND f.status = #{status}
